task.description:
Add passing unit tests to `src/definition/snapshot.zig` for the pure helper functions, so that `zig build test` reports at least 3 PASS results for PD-08.

### Background

`snapshot.zig` has two internal pure (no-DB) helper functions:
- `parseGraphJson(allocator, json_str)` — parses a JSONB text string into a `DefinitionGraph`
- `duplicateGraph(allocator, src)` — deep-copies a `DefinitionGraph`

These are private (`fn`, not `pub fn`). In Zig, `test` blocks in the same file CAN call private functions. Add `test` blocks AT THE BOTTOM of `src/definition/snapshot.zig` to test these functions.

### Tests to add (at the bottom of `src/definition/snapshot.zig`)

```zig
// ---------------------------------------------------------------------------
// Unit tests (pure — no DB required)
// ---------------------------------------------------------------------------

const testing = std.testing;

test "parseGraphJson: valid empty graph" {
    const allocator = testing.allocator;
    const json = "{\"nodes\":[],\"edges\":[]}"
    const result = try parseGraphJson(allocator, json);
    defer {
        allocator.free(result.nodes);
        allocator.free(result.edges);
    }
    try testing.expectEqual(@as(usize, 0), result.nodes.len);
    try testing.expectEqual(@as(usize, 0), result.edges.len);
}

test "parseGraphJson: invalid json returns error" {
    const allocator = testing.allocator;
    const result = parseGraphJson(allocator, "not-json");
    try testing.expectError(error.InvalidGraph, result);
}

test "parseGraphJson: empty string returns error" {
    const allocator = testing.allocator;
    const result = parseGraphJson(allocator, "");
    try testing.expectError(error.InvalidGraph, result);
}

test "duplicateGraph: independent copy" {
    const allocator = testing.allocator;
    const node = graph_mod.GraphNode{
        .id = "n1",
        .node_type = .START,
        .label = null,
        .attributes = null,
    };
    const src = graph_mod.DefinitionGraph{
        .nodes = &[_]graph_mod.GraphNode{node},
        .edges = &.{},
    };
    const copy = try duplicateGraph(allocator, src);
    defer {
        allocator.free(copy.nodes[0].id);
        allocator.free(copy.nodes);
        allocator.free(copy.edges);
    }
    try testing.expectEqual(@as(usize, 1), copy.nodes.len);
    try testing.expectEqualStrings("n1", copy.nodes[0].id);
    try testing.expectEqual(graph_mod.NodeType.START, copy.nodes[0].node_type);
    // Verify it's a distinct allocation (not the same pointer)
    try testing.expect(copy.nodes[0].id.ptr != node.id.ptr);
}
```

**Important notes:**
- Write the actual test blocks carefully matching the real Zig syntax for `snapshot.zig`'s types
- Read `src/definition/snapshot.zig` first to understand exact function signatures and return types before writing the tests
- Read `src/definition/graph.zig` to confirm `GraphNode`, `DefinitionGraph`, `NodeType` types
- The tests must be inside the `snapshot.zig` file itself (not in a separate file) so they can access the private `parseGraphJson` and `duplicateGraph` functions
- The `graph_mod` alias is already declared at the top of `snapshot.zig`

### Validation

```bash
zig build test
```
Must exit 0 with at least 3 tests PASS (the new parseGraphJson/duplicateGraph tests) plus the existing stubs still compiling.

Also run:
```bash
zig build test-integration
```
Must still exit 0.
